 * the dead cells touching them. A birth needs 3 live neighbours, so a cell with
 * no live neighbour at all can never turn on.
 */
function candidates(liveCells: Cell[]): Cell[] {
  const seen: Cell[] = [];
  for (const [x, y] of liveCells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const candidate: Cell = [x + dx, y + dy];
        if (!isAlive(candidate, seen)) seen.push(candidate);
