export type Cell = [number, number];

function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  return x === otherX && y === otherY;
}

function isAdjacent([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  return Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
}

function isNeighbor(cell: Cell, other: Cell): boolean {
  return isAdjacent(cell, other) && !isSameCell(cell, other);
}

function liveNeighborCount(cell: Cell, liveCells: Cell[]): number {
  return liveCells.filter((other) => isNeighbor(cell, other)).length;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => {
    const neighborCount = liveNeighborCount(cell, liveCells);
    return neighborCount >= 2 && neighborCount <= 3;
  });
}

